text(matches);
const r = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la && rg --files",workdir:"/workspace",max_output_tokens:2000}),
  tools.exec_command({cmd:"/opt/reference/executable --help",workdir:"/tmp",max_output_tokens:2000})
]);
for (const x of r) text(x);

