text(p);
const r=await Promise.all([
 tools.exec_command({cmd:"/opt/reference/executable --version; sed -n '1,240p' docs/audits.md",workdir:"/tmp",max_output_tokens:4000}),
 tools.exec_command({cmd:"cat docs/snippets/help.txt",workdir:"/workspace",max_output_tokens:1500})
]);
for(const x of r) text(x.output);

